(() => {
  'use strict';

  const style = document.createElement('style');
  style.textContent = `
    .freeTag{display:inline-block;margin-left:8px;padding:3px 8px;border:1px solid var(--line);border-radius:999px;color:var(--accent2);font-size:11px;font-weight:800}
    .toolCard.newFree{border-color:#3b4650}
    .fullCard{border:1px solid var(--line);background:var(--panel);border-radius:14px;padding:22px;margin-top:18px}
    .toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:end;margin:12px 0}
    .toolbar .field,.toolbar .selectField{min-width:160px;flex:1}
    .miniBtn{border:1px solid var(--line);background:#14202b;color:var(--text);border-radius:8px;padding:9px 11px;cursor:pointer;font:inherit}
    .miniBtn:hover{border-color:#50657a}.dangerBtn{border-color:#633;color:#f1b7b7}.accentBtn{border-color:#80662f;color:var(--accent2)}
    .dataWrap{overflow-x:auto;margin-top:12px}.dataTable{width:100%;border-collapse:collapse;min-width:860px}.dataTable th,.dataTable td{border-bottom:1px solid var(--line);padding:7px 6px;font-size:12px;white-space:nowrap;text-align:right}.dataTable th{color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.06em}.dataTable th:first-child,.dataTable td:first-child,.dataTable th:nth-child(2),.dataTable td:nth-child(2){text-align:left}.dataTable input,.dataTable select{width:100%;min-width:90px;border:1px solid #344454;border-radius:7px;background:#0c131a;color:var(--text);padding:7px 8px}.dataTable input.wide{min-width:140px}
    .quickRows{display:grid;grid-template-columns:110px repeat(3,minmax(0,1fr));gap:10px;align-items:end}.rowName{align-self:center;font-size:13px;font-weight:800;color:var(--accent2);padding-top:22px}
    .graphGrid{display:grid;grid-template-columns:1fr;gap:18px;margin-top:18px}.graphTabs{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:10px}.graphTab{border:1px solid var(--line);background:#0d151d;color:var(--muted);padding:8px 10px;border-radius:8px;cursor:pointer}.graphTab.active{color:var(--text);border-color:#80662f;background:#171d20}.canvasWrap{border:1px solid var(--line);border-radius:12px;background:#0c131a;padding:12px}.monitorCanvas{display:block;width:100%;height:340px}.graphNote{font-size:12px;color:var(--muted);margin-top:8px}
    .fileInput{position:absolute;left:-9999px}.uploadLabel{display:inline-flex;align-items:center;border:1px solid var(--line);background:#14202b;color:var(--text);border-radius:8px;padding:9px 11px;cursor:pointer;font-size:13px}
    .summaryGrid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-top:12px}.summaryBox{border:1px solid var(--line);border-radius:10px;background:#0d151d;padding:12px}.summaryBox small{display:block;color:var(--muted);margin-bottom:5px}.summaryBox strong{font-size:18px}
    .codeHint{font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:12px;color:var(--muted)}
    .twoCol{display:grid;grid-template-columns:1fr 1fr;gap:18px}.threeCol{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
    .textArea{width:100%;min-height:190px;border:1px solid #344454;border-radius:9px;background:#0c131a;color:var(--text);padding:12px;font:13px ui-monospace,SFMono-Regular,Consolas,monospace;resize:vertical}
    .statusLine{margin-top:12px;padding:11px 13px;border:1px solid var(--line);border-radius:10px;background:#0d151d;color:var(--muted);font-size:13px}.statusLine.good{border-color:#315b49;color:#bfe6d3}.statusLine.warn{border-color:#735d2d;color:#f5d58b}
    .pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 7px;font-size:10px;color:var(--muted)}
    @media(max-width:900px){.summaryGrid{grid-template-columns:1fr 1fr}.twoCol{grid-template-columns:1fr}.quickRows{grid-template-columns:90px repeat(3,minmax(0,1fr))}}
    @media(max-width:620px){.summaryGrid,.threeCol{grid-template-columns:1fr}.quickRows{grid-template-columns:1fr}.rowName{padding-top:8px}.monitorCanvas{height:280px}}
  `;
  document.head.appendChild(style);

  const esc = s => String(s ?? '').replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
  const num = v => { const x = parseFloat(v); return Number.isFinite(x) ? x : NaN; };
  const signed = (v,d=3) => Number.isFinite(v) ? `${v>=0?'+':''}${v.toFixed(d)}` : '—';
  const fixed = (v,d=3) => Number.isFinite(v) ? v.toFixed(d) : '—';
  const toRad = d => d*Math.PI/180;
  const toDeg = r => r*180/Math.PI;
  const normBearing = b => (b%360+360)%360;
  const resultBox = (label,value) => `<div class="result"><small>${label}</small><strong>${value}</strong></div>`;
  const status = (id,msg,kind='') => { const el=document.getElementById(id); if(el){el.className=`statusLine ${kind}`;el.innerHTML=msg;} };

  function parseBearing(v){
    const s=String(v??'').trim(); if(!s) return NaN;
    if(/^[-+]?\d+(\.\d+)?$/.test(s)) return normBearing(parseFloat(s));
    const parts=s.replace(/[°ºd]/gi,' ').replace(/[′'m]/gi,' ').replace(/[″"s]/gi,' ').split(/[\s,:]+/).filter(Boolean).map(Number);
    if(parts.length>=2 && parts.every(Number.isFinite)) return normBearing((parts[0]<0?-1:1)*(Math.abs(parts[0])+(parts[1]||0)/60+(parts[2]||0)/3600));
    return NaN;
  }
  function dms(v){
    if(!Number.isFinite(v)) return '—'; v=normBearing(v); let d=Math.floor(v),m0=(v-d)*60,m=Math.floor(m0),s=(m0-m)*60;
    if(s>=59.9995){s=0;m++;} if(m>=60){m=0;d=(d+1)%360;}
    return `${d}° ${String(m).padStart(2,'0')}′ ${s.toFixed(2).padStart(5,'0')}″`;
  }

  // ---------- Navigation / cards ----------
  const NEW_TOOLS = [
    ['10','Bowditch Traverse','Full traverse legs, closure, relative precision, Bowditch corrections and adjusted coordinates.','bowditch'],
    ['11','Level Traverse','Field-book style BS / IS / FS level run with misclose and adjusted RLs.','levelrun'],
    ['12','Drillhole Toe','Collar coordinate + azimuth + dip + hole length → toe coordinate.','drilltoe'],
    ['13','Bench & Batter','Bench height, batter angle and berm width geometry for quick pit checks.','batter'],
    ['14','Chainage & Offset','Chainage, signed offset and closest point from a point to a design line.','chainage'],
    ['15','Slope Distance Reducer','Reduce slope distance and vertical/zenith angle to horizontal and vertical components.','slopereduce'],
    ['16','Control Comparison','Compare known vs observed control coordinates across multiple points.','controlcheck'],
    ['17','Polygon Area & Perimeter','Paste Easting/Northing coordinates and calculate area, perimeter and centroid.','polygon'],
    ['18','Trimble JXL Extractor','Extract only points actually observed in a Trimble JXL and export reduced E/N/RL to CSV.','jxlcsv']
  ];

  function addCards(){
    const grid=document.getElementById('toolGrid'); if(!grid || grid.dataset.freeV1==='1') return;
    grid.dataset.freeV1='1';
    NEW_TOOLS.forEach(t=>{
      const el=document.createElement('div'); el.className='toolCard newFree';
      el.innerHTML=`<span class="toolNum">TOOL ${t[0]}</span><h3>${t[1]} <span class="freeTag">FREE</span></h3><p>${t[2]}</p><span class="open">Open tool →</span>`;
      el.addEventListener('click',()=>window.openTool(t[3])); grid.appendChild(el);
    });
    const prismCard=[...grid.querySelectorAll('.toolCard')].find(x=>x.textContent.includes('Prism Movement'));
    if(prismCard){const p=prismCard.querySelector('p'); if(p)p.textContent='Import JXL/CSV monitoring rounds, compare baseline or previous observations, and inspect movement in multiple graph views.';}
  }

  const closeBtn = () => `<button class="close" data-close-tool>← Close</button>`;
  const mount = html => { const a=document.getElementById('calcArea'); a.innerHTML=html; a.querySelector('[data-close-tool]')?.addEventListener('click',()=>a.innerHTML=''); a.scrollIntoView({behavior:'smooth',block:'start'}); return a; };
  const input = (id,label,value='',type='number') => `<div class="field"><label for="${id}">${label}</label><input id="${id}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(value)}"></div>`;

  // ---------- Trimble JXL parser ----------
  function childText(parent,tag){ const el=[...parent.children].find(x=>x.localName===tag || x.tagName===tag); return el?.textContent?.trim() ?? ''; }
  function descendants(root,tag){ return [...root.getElementsByTagName('*')].filter(x=>x.localName===tag || x.tagName===tag); }
  function parseTrimbleJXL(text,fileName='monitoring.jxl'){
    const doc=new DOMParser().parseFromString(text,'application/xml');
    if(doc.querySelector('parsererror')) throw new Error('This file could not be parsed as XML / Trimble JobXML.');
    const root=doc.documentElement;
    const jobName=root.getAttribute('jobName') || root.getAttribute('jobname') || fileName.replace(/\.jxl$/i,'');
    const timestamp=root.getAttribute('timeStamp') || root.getAttribute('timestamp') || '';
    const pointRecords=descendants(root,'PointRecord');
    const observed=new Map();
    pointRecords.forEach(pr=>{
      const method=childText(pr,'Method'); const deleted=childText(pr,'Deleted').toLowerCase()==='true'; const name=childText(pr,'Name');
      if(method==='DirectReading' && !deleted && name){
        const rec=observed.get(name)||{shots:0,faces:new Set(),times:[]}; rec.shots++;
        const circle=[...pr.children].find(x=>x.localName==='Circle'); const face=circle?childText(circle,'Face'):''; if(face)rec.faces.add(face);
        const ts=pr.getAttribute('TimeStamp')||pr.getAttribute('timestamp'); if(ts)rec.times.push(ts); observed.set(name,rec);
      }
    });
    const reductions=descendants(root,'Reductions')[0]; if(!reductions) throw new Error('No <Reductions> section was found in this JXL.');
    const reduced=[];
    [...reductions.children].filter(x=>x.localName==='Point'||x.tagName==='Point').forEach(pt=>{
      const name=childText(pt,'Name'); if(!observed.has(name)) return;
      const grid=[...pt.children].find(x=>x.localName==='Grid'||x.tagName==='Grid'); if(!grid) return;
      const n=num(childText(grid,'North')),e=num(childText(grid,'East')),rl=num(childText(grid,'Elevation'));
      if([e,n,rl].every(Number.isFinite)){
        const raw=observed.get(name); reduced.push({id:name,e,n,rl,shots:raw.shots,faces:[...raw.faces].join('/'),source:'JXL',fileName,jobName,timestamp});
      }
    });
    reduced.sort((a,b)=>a.id.localeCompare(b.id,undefined,{numeric:true}));
    return {jobName,timestamp,observedCount:observed.size,reduced,rawCount:[...observed.values()].reduce((s,r)=>s+r.shots,0)};
  }
  function readFileText(file){ return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result??''));r.onerror=()=>reject(r.error||new Error('Could not read file'));r.readAsText(file);}); }
  function downloadText(name,text,type='text/csv'){ const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000); }
  function csvEscape(v){const s=String(v??'');return /[",\n\r]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}

  // ---------- Prism Monitoring v2 ----------
  let prismRows=[]; let prismKey=1; let prismGraph='plan';
  const movement=(a,b)=>{const de=b.e-a.e,dn=b.n-a.n,dz=b.rl-a.rl,h=Math.hypot(de,dn),m=Math.hypot(h,dz);return{de,dn,dz,h,m,bearing:h?normBearing(toDeg(Math.atan2(de,dn))):null};};
  function makePrismRow(o){return{key:`pr${prismKey++}`,id:o.id||'PRISM',label:o.label||`Obs ${prismKey-1}`,dateText:o.dateText||'',time:Number.isFinite(o.time)?o.time:NaN,e:o.e,n:o.n,rl:o.rl,shots:o.shots??'',source:o.source||'Manual',fileName:o.fileName||'',order:prismKey-1};}
  function loadDemoPrisms(){
    const baseTime=Date.UTC(2026,6,1,0,0,0); prismRows=[]; prismKey=1;
    const demos=[
      {id:'DEMO-P01',e:408500.000,n:6950500.000,rl:470.000,steps:[[0,0,0],[2,-1,-1],[4,-3,-2],[8,-4,-4],[12,-7,-6],[17,-9,-8],[21,-12,-11],[27,-15,-14]]},
      {id:'DEMO-P02',e:408620.000,n:6950410.000,rl:468.500,steps:[[0,0,0],[-1,2,0],[-3,4,1],[-4,7,1],[-7,9,0],[-10,13,-1],[-13,16,-2],[-16,20,-3]]}
    ];
    demos.forEach(d=>d.steps.forEach((s,i)=>prismRows.push(makePrismRow({id:d.id,label:`Round ${i+1}`,dateText:new Date(baseTime+i*7*86400000).toLocaleDateString('en-AU'),time:baseTime+i*7*86400000,e:d.e+s[0]/1000,n:d.n+s[1]/1000,rl:d.rl+s[2]/1000,shots:2,source:'Demo'}))));
    refreshPrismSelector(demos[0].id); renderPrismDataset(); status('prismStatus','Loaded two synthetic demo prisms. They are example data only and disappear when the page is reloaded.','good');
  }
  function quickP(prefix){return{e:num(document.getElementById(prefix+'e')?.value),n:num(document.getElementById(prefix+'n')?.value),rl:num(document.getElementById(prefix+'r')?.value)};}
  function quickValid(p){return [p.e,p.n,p.rl].every(Number.isFinite);}
  function renderQuickPrism(){const old=quickP('qold'),cur=quickP('qnew'),r=document.getElementById('prismQuickResult');if(!r)return;if(!quickValid(old)||!quickValid(cur)){r.innerHTML=resultBox('Result','Enter valid coordinates');return;}const m=movement(old,cur);r.innerHTML=resultBox('ΔE',`${signed(m.de*1000,1)} mm`)+resultBox('ΔN',`${signed(m.dn*1000,1)} mm`)+resultBox('ΔRL',`${signed(m.dz*1000,1)} mm`)+resultBox('Horizontal',`${fixed(m.h*1000,1)} mm`)+resultBox('3D movement',`${fixed(m.m*1000,1)} mm`)+resultBox('Bearing',m.bearing==null?'No horizontal movement':dms(m.bearing));}
  function selectedPrismRows(){const id=document.getElementById('prismSelect')?.value||'';let rows=prismRows.filter(r=>r.id===id);if(rows.length>1&&rows.every(r=>Number.isFinite(r.time)))rows=[...rows].sort((a,b)=>a.time-b.time||a.order-b.order);else rows=[...rows].sort((a,b)=>a.order-b.order);return rows;}
  function refreshPrismSelector(preferred){const s=document.getElementById('prismSelect');if(!s)return;const ids=[...new Set(prismRows.map(r=>r.id))];const keep=preferred&&ids.includes(preferred)?preferred:(ids.includes(s.value)?s.value:ids[0]||'');s.innerHTML=ids.length?ids.map(id=>`<option value="${esc(id)}">${esc(id)}</option>`).join(''):'<option value="">No data</option>';s.value=keep;}
  function rowMove(rows,i){if(i===0)return{de:0,dn:0,dz:0,h:0,m:0,bearing:null};const mode=document.getElementById('prismCompare')?.value||'baseline';return movement(rows[mode==='previous'?i-1:0],rows[i]);}
  function renderPrismDataset(){const rows=selectedPrismRows(),body=document.getElementById('prismBody'),summary=document.getElementById('prismSummary');if(!body)return;if(!rows.length){body.innerHTML='<tr><td colspan="12" style="text-align:center;color:var(--muted);padding:20px">Load demo data, add observations, or import JXL / CSV files.</td></tr>';if(summary)summary.innerHTML='No dataset loaded.';drawPrismGraph([]);return;}
    body.innerHTML=rows.map((r,i)=>{const m=rowMove(rows,i);return `<tr><td>${esc(r.id)}</td><td>${esc(r.label)}</td><td>${r.dateText?esc(r.dateText):`#${i+1}`}</td><td>${fixed(r.e,3)}</td><td>${fixed(r.n,3)}</td><td>${fixed(r.rl,3)}</td><td>${signed(m.de*1000,1)}</td><td>${signed(m.dn*1000,1)}</td><td>${signed(m.dz*1000,1)}</td><td>${fixed(m.h*1000,1)}</td><td>${fixed(m.m*1000,1)}</td><td>${r.shots||'—'}</td></tr>`;}).join('');
    const latest=rowMove(rows,rows.length-1); if(summary)summary.innerHTML=`<div class="summaryGrid">${resultBox('Observations',rows.length)}${resultBox('Latest horizontal',`${fixed(latest.h*1000,1)} mm`)}${resultBox('Latest ΔRL',`${signed(latest.dz*1000,1)} mm`)}${resultBox('Latest 3D',`${fixed(latest.m*1000,1)} mm`)}</div>`; drawPrismGraph(rows);
  }
  function canvasInfo(){const c=document.getElementById('prismCanvas');if(!c)return null;const rect=c.getBoundingClientRect(),dpr=window.devicePixelRatio||1,w=Math.max(320,rect.width||900),h=Math.max(260,rect.height||340);c.width=Math.round(w*dpr);c.height=Math.round(h*dpr);const ctx=c.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);const cs=getComputedStyle(document.documentElement);return{c,ctx,w,h,t:{accent:cs.getPropertyValue('--accent').trim()||'#f2b84b',text:cs.getPropertyValue('--text').trim()||'#fff',muted:cs.getPropertyValue('--muted').trim()||'#9fb0bf',line:cs.getPropertyValue('--line').trim()||'#253341',panel:'#0c131a'}};}
  function nice(v){if(!Number.isFinite(v)||v<=0)return 10;const p=10**Math.floor(Math.log10(v)),n=v/p;return (n<=1?1:n<=2?2:n<=5?5:10)*p;}
  function drawAxes(ctx,w,h,t,minY,maxY,left=48,right=18,top=22,bottom=38){ctx.fillStyle=t.panel;ctx.fillRect(0,0,w,h);ctx.font='10px Arial';ctx.strokeStyle=t.line;ctx.fillStyle=t.muted;ctx.lineWidth=1;for(let i=0;i<=4;i++){const val=minY+(maxY-minY)*i/4,y=top+(maxY-val)*(h-top-bottom)/(maxY-minY);ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(w-right,y);ctx.stroke();ctx.fillText(fixed(val,Math.abs(maxY)<10?1:0),4,y+3);}ctx.strokeStyle=t.muted;ctx.beginPath();ctx.moveTo(left,top);ctx.lineTo(left,h-bottom);ctx.lineTo(w-right,h-bottom);ctx.stroke();return{left,right,top,bottom};}
  function drawPrismGraph(rows){const s=canvasInfo();if(!s)return;const{ctx,w,h,t}=s;ctx.clearRect(0,0,w,h);if(!rows.length){ctx.fillStyle=t.panel;ctx.fillRect(0,0,w,h);ctx.fillStyle=t.muted;ctx.font='12px Arial';ctx.textAlign='center';ctx.fillText('Load monitoring observations to graph movement.',w/2,h/2);ctx.textAlign='left';return;}
    if(prismGraph==='plan') return drawPlanPath(rows,s);
    const vals=rows.map((r,i)=>rowMove(rows,i)); let series=[];
    if(prismGraph==='components')series=[['ΔE',v=>v.de*1000,t.accent,[]],['ΔN',v=>v.dn*1000,t.muted,[5,4]],['ΔRL',v=>v.dz*1000,'#c9a7ff',[2,3]]];
    if(prismGraph==='magnitude')series=[['Horizontal',v=>v.h*1000,t.accent,[]],['3D',v=>v.m*1000,t.muted,[5,4]]];
    if(prismGraph==='rl')series=[['RL change',(_,i)=>(rows[i].rl-rows[0].rl)*1000,t.accent,[]]];
    const all=series.flatMap(sx=>vals.map((v,i)=>sx[1](v,i))).filter(Number.isFinite);let max=nice(Math.max(5,...all.map(Math.abs))*1.15),minY=prismGraph==='magnitude'?0:-max,maxY=max;if(prismGraph==='magnitude')maxY=nice(Math.max(5,...all)*1.15);
    const ax=drawAxes(ctx,w,h,t,minY,maxY),x=i=>ax.left+(rows.length===1?0:i*(w-ax.left-ax.right)/(rows.length-1)),y=v=>ax.top+(maxY-v)*(h-ax.top-ax.bottom)/(maxY-minY);ctx.fillStyle=t.muted;ctx.fillText('mm',6,13);
    series.forEach(([label,get,color,dash],si)=>{ctx.strokeStyle=color;ctx.lineWidth=2.3;ctx.setLineDash(dash);ctx.beginPath();vals.forEach((v,i)=>{const q=get(v,i);i?ctx.lineTo(x(i),y(q)):ctx.moveTo(x(i),y(q));});ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=color;vals.forEach((v,i)=>{ctx.beginPath();ctx.arc(x(i),y(get(v,i)),3.2,0,Math.PI*2);ctx.fill();});ctx.fillStyle=color;ctx.fillRect(ax.left+si*120,6,16,3);ctx.fillStyle=t.text;ctx.fillText(label,ax.left+22+si*120,10);});
    ctx.fillStyle=t.muted;ctx.textAlign='center';const step=Math.max(1,Math.ceil(rows.length/8));rows.forEach((r,i)=>{if(i%step===0||i===rows.length-1)ctx.fillText(String(i+1),x(i),h-14);});ctx.textAlign='left';
  }
  function drawPlanPath(rows,s){const{ctx,w,h,t}=s;const base=rows[0],pts=rows.map(r=>({e:(r.e-base.e)*1000,n:(r.n-base.n)*1000})),max=nice(Math.max(5,...pts.flatMap(p=>[Math.abs(p.e),Math.abs(p.n)]))*1.2),pad=46,cx=w/2,cy=h/2,scale=Math.min((w/2-pad)/max,(h/2-pad)/max);ctx.fillStyle=t.panel;ctx.fillRect(0,0,w,h);ctx.strokeStyle=t.line;ctx.fillStyle=t.muted;ctx.font='10px Arial';for(let i=-2;i<=2;i++){const v=max*i/2,x=cx+v*scale,y=cy-v*scale;ctx.beginPath();ctx.moveTo(x,18);ctx.lineTo(x,h-22);ctx.stroke();ctx.beginPath();ctx.moveTo(22,y);ctx.lineTo(w-18,y);ctx.stroke();if(i!==0){ctx.fillText(fixed(v,max<10?1:0),x+3,cy+13);ctx.fillText(fixed(v,max<10?1:0),cx+5,y-3);}}ctx.strokeStyle=t.accent;ctx.lineWidth=2.5;ctx.beginPath();pts.forEach((p,i)=>{const x=cx+p.e*scale,y=cy-p.n*scale;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();pts.forEach((p,i)=>{const x=cx+p.e*scale,y=cy-p.n*scale;ctx.fillStyle=i===0?t.muted:t.accent;ctx.beginPath();ctx.arc(x,y,i===pts.length-1?5:3.5,0,Math.PI*2);ctx.fill();});ctx.fillStyle=t.muted;ctx.fillText('ΔE (mm)',w-70,cy-8);ctx.fillText('ΔN (mm)',cx+8,16);}
  async function importJXLFiles(files){if(!files?.length)return;let imported=[],summaries=[];for(const f of files){try{const parsed=parseTrimbleJXL(await readFileText(f),f.name);const ts=parsed.timestamp?Date.parse(parsed.timestamp):NaN;parsed.reduced.forEach(p=>imported.push(makePrismRow({id:p.id,label:parsed.jobName,dateText:parsed.timestamp?new Date(parsed.timestamp).toLocaleString('en-AU'):f.name,time:Number.isFinite(ts)?ts:NaN,e:p.e,n:p.n,rl:p.rl,shots:p.shots,source:'JXL',fileName:f.name})));summaries.push(`${esc(f.name)}: ${parsed.reduced.length} observed reduced points / ${parsed.rawCount} raw shots`);}catch(e){summaries.push(`${esc(f.name)}: ERROR — ${esc(e.message)}`);}}
    if(imported.length){prismRows.push(...imported);refreshPrismSelector(imported[0].id);renderPrismDataset();status('prismStatus',`Imported ${imported.length} reduced observations from ${files.length} JXL file${files.length===1?'':'s'}.<br>${summaries.join('<br>')}`,'good');}else status('prismStatus',summaries.join('<br>'),'warn');
  }
  function parseCSV(text){const lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(x=>x.trim());if(lines.length<2)return[];const delim=(lines[0].match(/;/g)||[]).length>(lines[0].match(/,/g)||[]).length?';':',';const split=line=>{let out=[],cell='',q=false;for(let i=0;i<line.length;i++){const ch=line[i];if(q){if(ch==='"'&&line[i+1]==='"'){cell+='"';i++;}else if(ch==='"')q=false;else cell+=ch;}else if(ch==='"')q=true;else if(ch===delim){out.push(cell.trim());cell='';}else cell+=ch;}out.push(cell.trim());return out;};const hdr=split(lines[0]),H=s=>String(s).toLowerCase().replace(/[^a-z0-9]/g,''),hs=hdr.map(H),find=(exact,contains=[])=>{for(const v of exact){const i=hs.indexOf(H(v));if(i>=0)return i;}return hs.findIndex(x=>contains.some(v=>x.includes(H(v))));};const iE=find(['e','easting','x'],['easting','grideast']),iN=find(['n','northing','y'],['northing','gridnorth']),iR=find(['rl','z','elevation','level'],['reducedlevel','elevation']),iID=find(['id','point','prism','name','station'],['prismid','pointid','target']),iDT=find(['datetime','timestamp','dateandtime','epoch'],['datetime','timestamp']),iDate=iDT>=0?-1:find(['date'],['date']),iTime=iDT>=0?-1:find(['time'],['time']);if(iE<0||iN<0||iR<0)throw new Error(`Could not identify Easting, Northing and RL columns. Headings: ${hdr.join(', ')}`);return lines.slice(1).map((l,idx)=>{const c=split(l),e=num(c[iE]),n=num(c[iN]),rl=num(c[iR]);if(![e,n,rl].every(Number.isFinite))return null;const id=(iID>=0?c[iID]:'Imported')||'Imported',dt=iDT>=0?c[iDT]:[iDate>=0?c[iDate]:'',iTime>=0?c[iTime]:''].filter(Boolean).join(' '),time=dt?Date.parse(dt):NaN;return makePrismRow({id,label:dt||`Obs ${idx+1}`,dateText:dt,time:Number.isFinite(time)?time:NaN,e,n,rl,source:'CSV'});}).filter(Boolean);}
  async function importCSVFile(file){try{const rows=parseCSV(await readFileText(file));if(!rows.length)throw new Error('No valid observations found.');prismRows.push(...rows);refreshPrismSelector(rows[0].id);renderPrismDataset();status('prismStatus',`Imported ${rows.length} CSV observation${rows.length===1?'':'s'}.`,'good');}catch(e){status('prismStatus',esc(e.message),'warn');}}
  function quickToDataset(){const a=quickP('qold'),b=quickP('qnew');if(!quickValid(a)||!quickValid(b))return;const id=(document.getElementById('quickPrismId')?.value||'PRISM01').trim()||'PRISM01';prismRows=[makePrismRow({id,label:'Baseline',...a}),makePrismRow({id,label:'Current',...b})];refreshPrismSelector(id);renderPrismDataset();}
  function exportPrismCSV(){if(!prismRows.length)return;const rows=[['Prism ID','Observation','Date Time','Easting','Northing','RL','Raw Shots','Source','File']];prismRows.forEach(r=>rows.push([r.id,r.label,r.dateText,r.e,r.n,r.rl,r.shots,r.source,r.fileName]));downloadText('prism_monitoring_session.csv',rows.map(x=>x.map(csvEscape).join(',')).join('\n'));}
  function openPrism(){const a=mount(`<div class="calc active">${closeBtn()}<h2>Prism Monitoring <span class="freeTag">FREE v1</span></h2><p class="notice">Session-only monitoring viewer. Import Trimble JXL or CSV files, compare baseline/previous observations and inspect movement in several graph views. Nothing is saved to a database.</p>
    <div class="calcLayout"><section class="card"><h3>Quick comparison</h3><div class="quickRows"><div class="rowName">Old / baseline</div>${input('qolde','Easting','387452.335')}${input('qoldn','Northing','6765381.441')}${input('qoldr','RL','422.518')}<div class="rowName">New / current</div>${input('qnewe','Easting','387452.344')}${input('qnewn','Northing','6765381.433')}${input('qnewr','RL','422.514')}</div><div class="toolbar">${input('quickPrismId','Prism ID','PRISM01','text')}<button class="miniBtn" id="quickUse">Use pair as dataset ↓</button></div></section><aside class="card"><h3>Result</h3><div class="resultGrid" id="prismQuickResult"></div></aside></div>
    <div class="fullCard"><h3>Monitoring data</h3><div class="toolbar"><button class="miniBtn accentBtn" id="demoPrisms">Load 2 demo prisms</button><label class="uploadLabel" for="jxlFiles">Import JXL files</label><input id="jxlFiles" class="fileInput" type="file" accept=".jxl,.xml,text/xml,application/xml" multiple><label class="uploadLabel" for="prismCsvFile">Import CSV</label><input id="prismCsvFile" class="fileInput" type="file" accept=".csv,text/csv"><button class="miniBtn" id="exportPrism">Export session CSV</button><button class="miniBtn dangerBtn" id="clearPrism">Clear session</button></div><div class="toolbar"><div class="selectField"><label for="prismSelect">Prism / point</label><select id="prismSelect"><option>No data</option></select></div><div class="selectField"><label for="prismCompare">Movement compared with</label><select id="prismCompare"><option value="baseline">First observation / baseline</option><option value="previous">Previous observation</option></select></div></div><div id="prismSummary"></div><div id="prismStatus" class="statusLine">JXL processing happens only in your browser. The importer uses DirectReading point names from the FieldBook and then matches those points to reduced E/N/RL coordinates.</div><div class="dataWrap"><table class="dataTable"><thead><tr><th>Prism</th><th>Round</th><th>Date / order</th><th>E</th><th>N</th><th>RL</th><th>ΔE mm</th><th>ΔN mm</th><th>ΔRL mm</th><th>Horiz mm</th><th>3D mm</th><th>Shots</th></tr></thead><tbody id="prismBody"></tbody></table></div></div>
    <div class="fullCard"><h3>Graphs</h3><div class="graphTabs"><button class="graphTab active" data-graph="plan">Plan path</button><button class="graphTab" data-graph="components">ΔE / ΔN / ΔRL</button><button class="graphTab" data-graph="magnitude">Horizontal / 3D</button><button class="graphTab" data-graph="rl">RL change</button></div><div class="canvasWrap"><canvas id="prismCanvas" class="monitorCanvas"></canvas></div><div class="graphNote" id="graphNote">Plan path is always shown relative to the first observation so you can see the direction and shape of movement.</div></div></div>`);
    ['qolde','qoldn','qoldr','qnewe','qnewn','qnewr'].forEach(id=>document.getElementById(id).addEventListener('input',renderQuickPrism));document.getElementById('quickUse').addEventListener('click',quickToDataset);document.getElementById('demoPrisms').addEventListener('click',loadDemoPrisms);document.getElementById('jxlFiles').addEventListener('change',e=>importJXLFiles(e.target.files));document.getElementById('prismCsvFile').addEventListener('change',e=>importCSVFile(e.target.files?.[0]));document.getElementById('exportPrism').addEventListener('click',exportPrismCSV);document.getElementById('clearPrism').addEventListener('click',()=>{prismRows=[];refreshPrismSelector();renderPrismDataset();status('prismStatus','Session cleared. No monitoring data is stored long-term.');});document.getElementById('prismSelect').addEventListener('change',renderPrismDataset);document.getElementById('prismCompare').addEventListener('change',renderPrismDataset);a.querySelectorAll('[data-graph]').forEach(b=>b.addEventListener('click',()=>{prismGraph=b.dataset.graph;a.querySelectorAll('[data-graph]').forEach(x=>x.classList.toggle('active',x===b));const notes={plan:'Plan path is always relative to the first observation.',components:'Signed component movement. Positive ΔE = east, positive ΔN = north, positive ΔRL = up.',magnitude:'Horizontal and 3D movement magnitudes using the selected baseline/previous comparison.',rl:'Signed RL change from the selected baseline/previous comparison.'};document.getElementById('graphNote').textContent=notes[prismGraph];drawPrismGraph(selectedPrismRows());}));renderQuickPrism();refreshPrismSelector();renderPrismDataset();
  }

  // ---------- Bowditch ----------
  let bowRows=0;
  function bowRow(o={}){const i=++bowRows;return `<tr data-bow="${i}"><td><input class="wide bname" value="${esc(o.name||`Leg ${i}`)}"></td><td><input class="bbear wide" value="${esc(o.bearing||'')}" placeholder="123 45 30"></td><td><input class="bdist" type="number" step="any" value="${o.distance??''}"></td><td class="bde">—</td><td class="bdn">—</td><td class="bce">—</td><td class="bcn">—</td><td class="bae">—</td><td class="ban">—</td><td><button class="miniBtn dangerBtn bdel">×</button></td></tr>`;}
  function addBow(o){const b=document.getElementById('bowBody');b.insertAdjacentHTML('beforeend',bowRow(o));const tr=b.lastElementChild;tr.querySelectorAll('input').forEach(x=>x.addEventListener('input',calcBowditch));tr.querySelector('.bdel').addEventListener('click',()=>{tr.remove();calcBowditch();});}
  function calcBowditch(){const trs=[...document.querySelectorAll('#bowBody tr')],startE=num(document.getElementById('bowStartE')?.value),startN=num(document.getElementById('bowStartN')?.value),endE=num(document.getElementById('bowEndE')?.value),endN=num(document.getElementById('bowEndN')?.value);if(![startE,startN,endE,endN].every(Number.isFinite))return;let legs=[],sumD=0,sumE=0,sumN=0;trs.forEach(tr=>{const b=parseBearing(tr.querySelector('.bbear').value),d=num(tr.querySelector('.bdist').value);if(Number.isFinite(b)&&Number.isFinite(d)&&d>0){const de=d*Math.sin(toRad(b)),dn=d*Math.cos(toRad(b));legs.push({tr,b,d,de,dn});sumD+=d;sumE+=de;sumN+=dn;}else legs.push({tr,b,d});});const calcEndE=startE+sumE,calcEndN=startN+sumN,misE=calcEndE-endE,misN=calcEndN-endN,lin=Math.hypot(misE,misN),prec=lin>0?sumD/lin:Infinity;let e=startE,n=startN;legs.forEach(l=>{if(Number.isFinite(l.de)){const ce=sumD?(-misE*l.d/sumD):0,cn=sumD?(-misN*l.d/sumD):0,ae=l.de+ce,an=l.dn+cn;e+=ae;n+=an;l.tr.querySelector('.bde').textContent=signed(l.de,3);l.tr.querySelector('.bdn').textContent=signed(l.dn,3);l.tr.querySelector('.bce').textContent=signed(ce,4);l.tr.querySelector('.bcn').textContent=signed(cn,4);l.tr.querySelector('.bae').textContent=fixed(e,3);l.tr.querySelector('.ban').textContent=fixed(n,3);}else l.tr.querySelectorAll('td').forEach(()=>{});});const r=document.getElementById('bowSummary');r.innerHTML=resultBox('Total length',`${fixed(sumD,3)} m`)+resultBox('E misclose',`${signed(misE,4)} m`)+resultBox('N misclose',`${signed(misN,4)} m`)+resultBox('Linear misclose',`${fixed(lin,4)} m`)+resultBox('Relative precision',Number.isFinite(prec)?`1 : ${Math.round(prec).toLocaleString('en-AU')}`:'Perfect closure')+resultBox('Adjusted end',`${fixed(e,3)}, ${fixed(n,3)}`);}
  function openBowditch(){const a=mount(`<div class="calc active">${closeBtn()}<h2>Bowditch Traverse <span class="freeTag">FREE</span></h2><p class="notice">Enter traverse legs, a start coordinate and the known closing coordinate. Bearing accepts decimal degrees or DMS such as <span class="codeHint">123 45 30</span>.</p><div class="fullCard"><div class="threeCol">${input('bowStartE','Start Easting','400000')}${input('bowStartN','Start Northing','6800000')}${input('bowEndE','Known end Easting','400000')}${input('bowEndN','Known end Northing','6800000')}</div><div class="dataWrap"><table class="dataTable"><thead><tr><th>Leg</th><th>Bearing</th><th>Distance m</th><th>ΔE</th><th>ΔN</th><th>Corr E</th><th>Corr N</th><th>Adj E</th><th>Adj N</th><th></th></tr></thead><tbody id="bowBody"></tbody></table></div><div class="toolbar"><button class="miniBtn" id="addBow">+ Add leg</button><button class="miniBtn" id="demoBow">Load example</button></div></div><div class="card" style="margin-top:18px"><h3>Closure & adjustment</h3><div class="resultGrid" id="bowSummary"></div><p class="smallNote">Bowditch corrections are distributed in proportion to each leg length. Acceptance limits depend on your survey class, site procedure and purpose.</p></div></div>`);bowRows=0;[['AB','45 00 00',100],['BC','135 00 00',100],['CD','225 00 00',100],['DA','315 00 20',99.99]].forEach(x=>addBow({name:x[0],bearing:x[1],distance:x[2]}));['bowStartE','bowStartN','bowEndE','bowEndN'].forEach(id=>document.getElementById(id).addEventListener('input',calcBowditch));document.getElementById('addBow').addEventListener('click',()=>addBow());document.getElementById('demoBow').addEventListener('click',()=>{document.getElementById('bowBody').innerHTML='';bowRows=0;[['ST01-ST02','32 18 20',124.32],['ST02-ST03','118 42 10',96.84],['ST03-ST04','214 10 40',115.52],['ST04-ST01','305 55 25',103.77]].forEach(x=>addBow({name:x[0],bearing:x[1],distance:x[2]}));calcBowditch();});calcBowditch();}

  // ---------- Level traverse ----------
  let levelRows=0;
  function levelRow(o={}){const i=++levelRows;return `<tr data-lr="${i}"><td><input class="wide lp" value="${esc(o.point||`P${i}`)}"></td><td><input class="lbs" type="number" step="any" value="${o.bs??''}"></td><td><input class="lis" type="number" step="any" value="${o.is??''}"></td><td><input class="lfs" type="number" step="any" value="${o.fs??''}"></td><td class="lhi">—</td><td class="lrl">—</td><td class="lrf">—</td><td class="ladj">—</td><td><button class="miniBtn dangerBtn ldel">×</button></td></tr>`;}
  function addLevel(o){const b=document.getElementById('levelBody');b.insertAdjacentHTML('beforeend',levelRow(o));const tr=b.lastElementChild;tr.querySelectorAll('input').forEach(x=>x.addEventListener('input',calcLevel));tr.querySelector('.ldel').addEventListener('click',()=>{tr.remove();calcLevel();});}
  function calcLevel(){const trs=[...document.querySelectorAll('#levelBody tr')],start=num(document.getElementById('levelStartRL')?.value),known=num(document.getElementById('levelKnownEnd')?.value);if(!Number.isFinite(start))return;let hi=NaN,currentRL=start,lastRL=start,fsCount=0,validRows=[];trs.forEach((tr,i)=>{const bs=num(tr.querySelector('.lbs').value),is=num(tr.querySelector('.lis').value),fs=num(tr.querySelector('.lfs').value);let rl=NaN,riseFall='—';if(i===0){rl=start;if(Number.isFinite(bs))hi=rl+bs;}else{if(Number.isFinite(is)&&Number.isFinite(hi))rl=hi-is;else if(Number.isFinite(fs)&&Number.isFinite(hi)){rl=hi-fs;fsCount++;}else if(Number.isFinite(bs)&&Number.isFinite(currentRL))rl=currentRL;if(Number.isFinite(rl)&&Number.isFinite(lastRL)){const d=rl-lastRL;riseFall=d>0?`Rise ${fixed(d,3)}`:d<0?`Fall ${fixed(-d,3)}`:'Level';}if(Number.isFinite(rl)&&Number.isFinite(bs))hi=rl+bs;}if(Number.isFinite(rl)){currentRL=rl;lastRL=rl;validRows.push({tr,rl,fsCount});}tr.querySelector('.lhi').textContent=Number.isFinite(hi)?fixed(hi,3):'—';tr.querySelector('.lrl').textContent=Number.isFinite(rl)?fixed(rl,3):'—';tr.querySelector('.lrf').textContent=riseFall;});const calcEnd=validRows.length?validRows[validRows.length-1].rl:NaN,mis=Number.isFinite(known)?calcEnd-known:NaN,totalSetups=Math.max(1,fsCount);validRows.forEach(v=>{const corr=Number.isFinite(mis)?(-mis*(v.fsCount/totalSetups)):0;v.tr.querySelector('.ladj').textContent=fixed(v.rl+corr,3);});document.getElementById('levelSummary').innerHTML=resultBox('Calculated end RL',`${fixed(calcEnd,3)} m`)+resultBox('Known end RL',Number.isFinite(known)?`${fixed(known,3)} m`:'Not entered')+resultBox('Misclose',Number.isFinite(mis)?`${signed(mis*1000,1)} mm`:'—')+resultBox('FS / setups',fsCount)+resultBox('Correction method','Equal by setup')+resultBox('Adjusted end',Number.isFinite(calcEnd)&&Number.isFinite(mis)?`${fixed(calcEnd-mis,3)} m`:'—');}
  function openLevelRun(){const a=mount(`<div class="calc active">${closeBtn()}<h2>Level Traverse <span class="freeTag">FREE</span></h2><p class="notice">Height-of-collimation field-book style. A change point can have both an FS and BS on the same row. The adjusted RL column distributes misclose equally by completed setup.</p><div class="fullCard"><div class="threeCol">${input('levelStartRL','Known start RL','100.000')}${input('levelKnownEnd','Known end RL','99.842')}</div><div class="dataWrap"><table class="dataTable"><thead><tr><th>Point</th><th>BS</th><th>IS</th><th>FS</th><th>HI</th><th>RL</th><th>Rise / Fall</th><th>Adj RL</th><th></th></tr></thead><tbody id="levelBody"></tbody></table></div><div class="toolbar"><button class="miniBtn" id="addLevel">+ Add row</button><button class="miniBtn" id="demoLevel">Load example</button></div></div><div class="card" style="margin-top:18px"><h3>Level run result</h3><div class="resultGrid" id="levelSummary"></div></div></div>`);levelRows=0;[{point:'BM01',bs:1.435},{point:'P01',is:1.982},{point:'TP01',fs:2.164,bs:1.824},{point:'P02',is:1.301},{point:'BM02',fs:1.952}].forEach(addLevel);['levelStartRL','levelKnownEnd'].forEach(id=>document.getElementById(id).addEventListener('input',calcLevel));document.getElementById('addLevel').addEventListener('click',()=>addLevel());document.getElementById('demoLevel').addEventListener('click',()=>{document.getElementById('levelBody').innerHTML='';levelRows=0;[{point:'BM01',bs:1.435},{point:'P01',is:1.982},{point:'TP01',fs:2.164,bs:1.824},{point:'P02',is:1.301},{point:'BM02',fs:1.952}].forEach(addLevel);calcLevel();});calcLevel();}

  // ---------- Small mine tools ----------
  function openDrillToe(){const a=mount(`<div class="calc active">${closeBtn()}<h2>Drillhole / Blast-hole Toe <span class="freeTag">FREE</span></h2><p class="notice">Dip is measured below horizontal: 0° = horizontal, 90° = vertical down.</p><div class="calcLayout"><section class="card"><div class="threeCol">${input('dtE','Collar Easting','408500')}${input('dtN','Collar Northing','6950500')}${input('dtRL','Collar RL','480')}${input('dtAz','Azimuth / bearing','135','text')}${input('dtDip','Dip below horizontal (°)','70')}${input('dtLen','Hole length (m)','18.5')}</div></section><aside class="card"><h3>Toe result</h3><div class="resultGrid" id="dtResult"></div></aside></div></div>`);const f=()=>{const e=num(document.getElementById('dtE').value),n=num(document.getElementById('dtN').value),rl=num(document.getElementById('dtRL').value),az=parseBearing(document.getElementById('dtAz').value),dip=num(document.getElementById('dtDip').value),L=num(document.getElementById('dtLen').value),hd=L*Math.cos(toRad(dip)),drop=L*Math.sin(toRad(dip)),de=hd*Math.sin(toRad(az)),dn=hd*Math.cos(toRad(az));document.getElementById('dtResult').innerHTML=resultBox('Toe Easting',fixed(e+de,3))+resultBox('Toe Northing',fixed(n+dn,3))+resultBox('Toe RL',fixed(rl-drop,3))+resultBox('Horizontal displacement',`${fixed(hd,3)} m`)+resultBox('Vertical drop',`${fixed(drop,3)} m`)+resultBox('ΔE / ΔN',`${signed(de,3)} / ${signed(dn,3)} m`);};a.querySelectorAll('input').forEach(x=>x.addEventListener('input',f));f();}
  function openBatter(){const a=mount(`<div class="calc active">${closeBtn()}<h2>Bench & Batter <span class="freeTag">FREE</span></h2><p class="notice">Quick geometric check. Batter angle is measured from horizontal.</p><div class="calcLayout"><section class="card"><div class="threeCol">${input('batH','Bench height (m)','10')}${input('batA','Batter angle (°)','70')}${input('batB','Berm width (m)','6')}${input('batCount','Number of benches','3')}</div></section><aside class="card"><h3>Result</h3><div class="resultGrid" id="batResult"></div></aside></div></div>`);const f=()=>{const h=num(document.getElementById('batH').value),ang=num(document.getElementById('batA').value),berm=num(document.getElementById('batB').value),count=Math.max(1,Math.round(num(document.getElementById('batCount').value)||1)),off=h/Math.tan(toRad(ang)),slope=h/Math.sin(toRad(ang)),totalV=h*count,totalH=off*count+berm*Math.max(0,count-1),overall=toDeg(Math.atan2(totalV,totalH));document.getElementById('batResult').innerHTML=resultBox('Batter horizontal offset',`${fixed(off,3)} m`)+resultBox('Batter slope length',`${fixed(slope,3)} m`)+resultBox('Bench + batter width',`${fixed(off+berm,3)} m`)+resultBox('Total vertical',`${fixed(totalV,3)} m`)+resultBox('Total horizontal',`${fixed(totalH,3)} m`)+resultBox('Overall angle',`${fixed(overall,3)}°`);};a.querySelectorAll('input').forEach(x=>x.addEventListener('input',f));f();}
  function openChainage(){const a=mount(`<div class="calc active">${closeBtn()}<h2>Point → Line Chainage & Offset <span class="freeTag">FREE</span></h2><p class="notice">Chainage is measured from A toward B. Positive offset is to the left of line A→B in the E/N plane.</p><div class="calcLayout"><section class="card"><div class="threeCol">${input('caE','A Easting','400000')}${input('caN','A Northing','6800000')}${input('cbE','B Easting','400100')}${input('cbN','B Northing','6800100')}${input('cpE','Point Easting','400060')}${input('cpN','Point Northing','6800040')}</div></section><aside class="card"><h3>Result</h3><div class="resultGrid" id="chainResult"></div></aside></div></div>`);const f=()=>{const ax=num(document.getElementById('caE').value),ay=num(document.getElementById('caN').value),bx=num(document.getElementById('cbE').value),by=num(document.getElementById('cbN').value),px=num(document.getElementById('cpE').value),py=num(document.getElementById('cpN').value),dx=bx-ax,dy=by-ay,L=Math.hypot(dx,dy);if(!L)return;const ux=dx/L,uy=dy/L,vx=px-ax,vy=py-ay,ch=vx*ux+vy*uy,off=ux*vy-uy*vx,ce=ax+ch*ux,cn=ay+ch*uy;document.getElementById('chainResult').innerHTML=resultBox('Chainage from A',`${fixed(ch,3)} m`)+resultBox('Signed offset',`${signed(off,3)} m`)+resultBox('Side',Math.abs(off)<1e-9?'On line':off>0?'Left':'Right')+resultBox('Closest Easting',fixed(ce,3))+resultBox('Closest Northing',fixed(cn,3))+resultBox('Line length',`${fixed(L,3)} m`);};a.querySelectorAll('input').forEach(x=>x.addEventListener('input',f));f();}
  function openSlopeReduce(){const a=mount(`<div class="calc active">${closeBtn()}<h2>Slope Distance Reducer <span class="freeTag">FREE</span></h2><p class="notice">Choose whether your vertical observation is a zenith angle or an angle from horizontal.</p><div class="calcLayout"><section class="card"><div class="threeCol">${input('srS','Slope distance (m)','100')}${input('srA','Vertical / zenith angle (°)','92')}<div class="selectField"><label for="srMode">Angle convention</label><select id="srMode"><option value="zenith">Zenith angle (0° up, 90° horizontal)</option><option value="horizontal">Angle from horizontal (+ up / - down)</option></select></div>${input('srRL','Start RL (optional)','100')}</div></section><aside class="card"><h3>Reduced result</h3><div class="resultGrid" id="srResult"></div></aside></div></div>`);const f=()=>{const s=num(document.getElementById('srS').value),a0=num(document.getElementById('srA').value),mode=document.getElementById('srMode').value,start=num(document.getElementById('srRL').value);let hd,vd;if(mode==='zenith'){hd=s*Math.sin(toRad(a0));vd=s*Math.cos(toRad(a0));}else{hd=s*Math.cos(toRad(a0));vd=s*Math.sin(toRad(a0));}document.getElementById('srResult').innerHTML=resultBox('Horizontal distance',`${fixed(hd,3)} m`)+resultBox('Vertical difference',`${signed(vd,3)} m`)+resultBox('End RL',Number.isFinite(start)?`${fixed(start+vd,3)} m`:'—')+resultBox('Grade',hd?`${fixed(vd/hd*100,3)}%`:'—');};a.querySelectorAll('input,select').forEach(x=>x.addEventListener('input',f));f();}

  // ---------- Control comparison ----------
  let ctrlRows=0;
  function ctrlRow(o={}){const i=++ctrlRows;return `<tr data-ctrl="${i}"><td><input class="wide cid" value="${esc(o.id||`CP${i}`)}"></td><td><input class="cke" type="number" step="any" value="${o.ke??''}"></td><td><input class="ckn" type="number" step="any" value="${o.kn??''}"></td><td><input class="ckr" type="number" step="any" value="${o.kr??''}"></td><td><input class="coe" type="number" step="any" value="${o.oe??''}"></td><td><input class="con" type="number" step="any" value="${o.on??''}"></td><td><input class="cor" type="number" step="any" value="${o.or??''}"></td><td class="cde">—</td><td class="cdn">—</td><td class="cdr">—</td><td class="ch">—</td><td class="c3">—</td><td><button class="miniBtn dangerBtn cdel">×</button></td></tr>`;}
  function addCtrl(o){const b=document.getElementById('ctrlBody');b.insertAdjacentHTML('beforeend',ctrlRow(o));const tr=b.lastElementChild;tr.querySelectorAll('input').forEach(x=>x.addEventListener('input',calcCtrl));tr.querySelector('.cdel').addEventListener('click',()=>{tr.remove();calcCtrl();});}
  function calcCtrl(){let hs=[],m3=[];document.querySelectorAll('#ctrlBody tr').forEach(tr=>{const ke=num(tr.querySelector('.cke').value),kn=num(tr.querySelector('.ckn').value),kr=num(tr.querySelector('.ckr').value),oe=num(tr.querySelector('.coe').value),on=num(tr.querySelector('.con').value),or=num(tr.querySelector('.cor').value),de=oe-ke,dn=on-kn,dr=or-kr,h=Math.hypot(de,dn),m=Math.hypot(h,dr);tr.querySelector('.cde').textContent=signed(de*1000,1);tr.querySelector('.cdn').textContent=signed(dn*1000,1);tr.querySelector('.cdr').textContent=signed(dr*1000,1);tr.querySelector('.ch').textContent=fixed(h*1000,1);tr.querySelector('.c3').textContent=fixed(m*1000,1);if(Number.isFinite(h)){hs.push(h);m3.push(m);}});document.getElementById('ctrlSummary').innerHTML=resultBox('Points checked',hs.length)+resultBox('Mean horizontal',`${fixed((hs.reduce((a,b)=>a+b,0)/(hs.length||1))*1000,1)} mm`)+resultBox('Max horizontal',`${fixed(Math.max(0,...hs)*1000,1)} mm`)+resultBox('Max 3D',`${fixed(Math.max(0,...m3)*1000,1)} mm`);}
  function openControl(){const a=mount(`<div class="calc active">${closeBtn()}<h2>Control Comparison <span class="freeTag">FREE</span></h2><p class="notice">One-off known vs observed control check. This does not save a control register.</p><div class="fullCard"><div class="dataWrap"><table class="dataTable"><thead><tr><th>ID</th><th>Known E</th><th>Known N</th><th>Known RL</th><th>Obs E</th><th>Obs N</th><th>Obs RL</th><th>ΔE mm</th><th>ΔN mm</th><th>ΔRL mm</th><th>Horiz mm</th><th>3D mm</th><th></th></tr></thead><tbody id="ctrlBody"></tbody></table></div><div class="toolbar"><button class="miniBtn" id="addCtrl">+ Add point</button></div></div><div class="card" style="margin-top:18px"><h3>Summary</h3><div class="resultGrid" id="ctrlSummary"></div></div></div>`);ctrlRows=0;addCtrl({id:'CP01',ke:400000,kn:6800000,kr:100,oe:400000.006,on:6799999.996,or:100.003});addCtrl({id:'CP02',ke:400100,kn:6800100,kr:102,oe:400100.011,on:6800100.004,or:101.998});document.getElementById('addCtrl').addEventListener('click',()=>addCtrl());calcCtrl();}

  // ---------- Polygon ----------
  function polygonCalc(){const txt=document.getElementById('polyText')?.value||'',pts=txt.split(/\r?\n/).map(l=>l.trim()).filter(Boolean).map(l=>l.split(/[\s,;\t]+/).map(Number)).filter(a=>a.length>=2&&a.slice(0,2).every(Number.isFinite)).map(a=>({x:a[0],y:a[1]})),r=document.getElementById('polyResult');if(pts.length<3){r.innerHTML=resultBox('Result','Enter at least 3 points');return;}let a2=0,per=0,cx=0,cy=0;for(let i=0;i<pts.length;i++){const p=pts[i],q=pts[(i+1)%pts.length],cross=p.x*q.y-q.x*p.y;a2+=cross;per+=Math.hypot(q.x-p.x,q.y-p.y);cx+=(p.x+q.x)*cross;cy+=(p.y+q.y)*cross;}const area=a2/2,abs=Math.abs(area);if(Math.abs(a2)>1e-12){cx/=3*a2;cy/=3*a2;}else{cx=NaN;cy=NaN;}r.innerHTML=resultBox('Area',`${fixed(abs,3)} m²`)+resultBox('Area',`${fixed(abs/10000,4)} ha`)+resultBox('Perimeter',`${fixed(per,3)} m`)+resultBox('Orientation',area>0?'Counter-clockwise':'Clockwise')+resultBox('Centroid E',fixed(cx,3))+resultBox('Centroid N',fixed(cy,3));}
  function openPolygon(){const a=mount(`<div class="calc active">${closeBtn()}<h2>Polygon Area & Perimeter <span class="freeTag">FREE</span></h2><p class="notice">Paste one Easting/Northing pair per line. The polygon closes automatically.</p><div class="calcLayout"><section class="card"><textarea id="polyText" class="textArea">400000,6800000\n400100,6800000\n400100,6800100\n400000,6800100</textarea></section><aside class="card"><h3>Result</h3><div class="resultGrid" id="polyResult"></div></aside></div></div>`);document.getElementById('polyText').addEventListener('input',polygonCalc);polygonCalc();}

  // ---------- JXL extractor ----------
  let jxlExtracted=[];
  function openJXL(){const a=mount(`<div class="calc active">${closeBtn()}<h2>Trimble JXL → Observed Coordinates CSV <span class="freeTag">FREE</span></h2><p class="notice">Select one or more Trimble JobXML files. The extractor keeps only points that were actually observed as DirectReading records, then matches them to the JXL reduced grid coordinates.</p><div class="fullCard"><div class="toolbar"><label class="uploadLabel" for="jxlExtractFiles">Choose JXL files</label><input id="jxlExtractFiles" class="fileInput" type="file" accept=".jxl,.xml,text/xml,application/xml" multiple><button class="miniBtn" id="jxlDownload" disabled>Download CSV</button></div><div id="jxlExtractStatus" class="statusLine">No file selected.</div><div class="dataWrap"><table class="dataTable"><thead><tr><th>File</th><th>Job</th><th>Prism / point</th><th>Easting</th><th>Northing</th><th>RL</th><th>Raw shots</th><th>Faces</th></tr></thead><tbody id="jxlExtractBody"><tr><td colspan="8" style="text-align:center;color:var(--muted)">Choose a JXL file.</td></tr></tbody></table></div></div></div>`);document.getElementById('jxlExtractFiles').addEventListener('change',async e=>{jxlExtracted=[];let msgs=[];for(const f of e.target.files){try{const p=parseTrimbleJXL(await readFileText(f),f.name);p.reduced.forEach(x=>jxlExtracted.push(x));msgs.push(`${esc(f.name)}: ${p.reduced.length} observed reduced points from ${p.rawCount} raw DirectReading shots.`);}catch(err){msgs.push(`${esc(f.name)}: ERROR — ${esc(err.message)}`);}}document.getElementById('jxlExtractBody').innerHTML=jxlExtracted.length?jxlExtracted.map(x=>`<tr><td>${esc(x.fileName)}</td><td>${esc(x.jobName)}</td><td>${esc(x.id)}</td><td>${fixed(x.e,3)}</td><td>${fixed(x.n,3)}</td><td>${fixed(x.rl,3)}</td><td>${x.shots}</td><td>${esc(x.faces||'—')}</td></tr>`).join(''):'<tr><td colspan="8" style="text-align:center">No reduced observed points found.</td></tr>';status('jxlExtractStatus',msgs.join('<br>'),jxlExtracted.length?'good':'warn');document.getElementById('jxlDownload').disabled=!jxlExtracted.length;});document.getElementById('jxlDownload').addEventListener('click',()=>{const rows=[['Source File','Job','Prism ID','Date Time','Easting','Northing','RL','Raw Shots','Faces']];jxlExtracted.forEach(x=>rows.push([x.fileName,x.jobName,x.id,x.timestamp,x.e,x.n,x.rl,x.shots,x.faces]));downloadText('observed_prisms_from_jxl.csv',rows.map(r=>r.map(csvEscape).join(',')).join('\n'));});}

  const oldOpen=window.openTool;
  window.openTool=function(k){
    if(k==='prism')return openPrism();
    if(k==='bowditch')return openBowditch();
    if(k==='levelrun')return openLevelRun();
    if(k==='drilltoe')return openDrillToe();
    if(k==='batter')return openBatter();
    if(k==='chainage')return openChainage();
    if(k==='slopereduce')return openSlopeReduce();
    if(k==='controlcheck')return openControl();
    if(k==='polygon')return openPolygon();
    if(k==='jxlcsv')return openJXL();
    return oldOpen(k);
  };

  addCards();
  const ver=[...document.querySelectorAll('.eyebrow')].find(x=>x.textContent.trim().startsWith('Version ')); if(ver)ver.textContent='Version 0.6 — Free v1';
  window.addEventListener('resize',()=>{if(document.getElementById('prismCanvas'))drawPrismGraph(selectedPrismRows());});

  // Expose a few pure helpers for QA harnesses.
  window.MSTFreeV1={parseBearing,parseTrimbleJXL,polygonCalcVersion:'1',movement};
})();
